def bar_tick(key, bar):
    """Tick of the downbeat of 1-based `bar`, honouring `pickup` and every meter change in `ts_events`."""
    m = MOVEMENTS[key]
    evs = m['ts_events']
    t, b = m['pickup'], 1
    for i, (et, num, den) in enumerate(evs):
        bt = 480 * 4 * num // den
        seg_end = evs[i + 1][0] if i + 1 < len(evs) else None
        start = max(t, et)
        if seg_end is None:
            return start + (bar - b) * bt
        n_bars = (seg_end - start) // bt
        if bar - b < n_bars:
            return start + (bar - b) * bt
        t, b = start + n_bars * bt, b + n_bars
    return t + (bar - b) * bt


def theme_window(key):
    """(from_tick, to_tick) of the movement's default theme window — inclusive bars, counted from the first downbeat (after the pickup)."""
    a, b = MOVEMENTS[key]['theme']
    return bar_tick(key, a), bar_tick(key, b + 1)


def theme_notes(key, part='solo', pad_bars=0, include_pickup=True):
    """Notes of `part` starting inside the theme window (plus `pad_bars` after), re-based so the window's first downbeat is tick 0.
    With include_pickup=True and theme starting at bar 1, the pickup notes are returned with negative ticks —
    callers must clamp or shift before humanising/encoding (negative ticks are invalid in SMF)."""
    m = MOVEMENTS[key]
    t0, _ = theme_window(key)
    t1 = bar_tick(key, m['theme'][1] + 1 + pad_bars)
    lo = 0 if (include_pickup and m['theme'][0] == 1) else t0
    return [(t - t0, d, p) for t, d, p in m['parts'][part] if lo <= t < t1]
